assign master_r_addr = (vexiiriscv_pbus_ar_payload_addr - 1'd0);
assign master_w_addr = (vexiiriscv_pbus_aw_payload_addr - 1'd0);
always @(*) begin
    master_adapted_interface_adr = 30'd0;
    master_adapted_interface_cyc = 1'd0;
    master_adapted_interface_dat_w = 32'd0;
    master_adapted_interface_sel = 4'd0;
    master_adapted_interface_stb = 1'd0;
