    master_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd0;
    master_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd0;
    socbushandler_axilite2wishbone_next_state = 3'd0;
    vexiiriscv_pbus_ar_ready = 1'd0;
    vexiiriscv_pbus_aw_ready = 1'd0;
    vexiiriscv_pbus_b_payload_resp = 2'd0;
    vexiiriscv_pbus_b_valid = 1'd0;
    vexiiriscv_pbus_r_payload_data = 32'd0;
    vexiiriscv_pbus_r_payload_resp = 2'd0;
    vexiiriscv_pbus_r_valid = 1'd0;
    vexiiriscv_pbus_w_ready = 1'd0;
    socbushandler_axilite2wishbone_next_state = socbushandler_axilite2wishbone_state;
    case (socbushandler_axilite2wishbone_state)
        1'd1: begin
            master_adapted_interface_stb = 1'd1;
            master_adapted_interface_cyc = 1'd1;
            master_adapted_interface_adr = master_r_addr[31:2];
            master_adapted_interface_sel = 4'd15;
            if (master_adapted_interface_ack) begin
                vexiiriscv_pbus_ar_ready = 1'd1;
                master_data_axilite2wishbone_next_value1 = master_adapted_interface_dat_r;
                master_data_axilite2wishbone_next_value_ce1 = 1'd1;
                socbushandler_axilite2wishbone_next_state = 2'd2;
            end
        end
        2'd2: begin
            vexiiriscv_pbus_r_valid = 1'd1;
            vexiiriscv_pbus_r_payload_resp = 1'd0;
            vexiiriscv_pbus_r_payload_data = master_data;
            if (vexiiriscv_pbus_r_ready) begin
                socbushandler_axilite2wishbone_next_state = 1'd0;
            end
        end
        2'd3: begin
            master_adapted_interface_stb = vexiiriscv_pbus_w_valid;
            master_adapted_interface_cyc = vexiiriscv_pbus_w_valid;
            master_adapted_interface_we = 1'd1;
            master_adapted_interface_adr = master_w_addr[31:2];
            master_adapted_interface_sel = vexiiriscv_pbus_w_payload_strb;
            master_adapted_interface_dat_w = vexiiriscv_pbus_w_payload_data;
            if (master_adapted_interface_ack) begin
                vexiiriscv_pbus_aw_ready = 1'd1;
                vexiiriscv_pbus_w_ready = 1'd1;
                socbushandler_axilite2wishbone_next_state = 3'd4;
            end
        end
        3'd4: begin
            vexiiriscv_pbus_b_valid = 1'd1;
            vexiiriscv_pbus_b_payload_resp = 1'd0;
            if (vexiiriscv_pbus_b_ready) begin
                socbushandler_axilite2wishbone_next_state = 1'd0;
            end
        end
        default: begin
            if ((vexiiriscv_pbus_ar_valid & vexiiriscv_pbus_aw_valid)) begin
                if (master_last_ar_aw_n) begin
                    master_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd0;
                    master_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd1;
                    socbushandler_axilite2wishbone_next_state = 2'd3;
                end else begin
                    master_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd1;
                    master_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd1;
                    socbushandler_axilite2wishbone_next_state = 1'd1;
                end
            end else begin
                if (vexiiriscv_pbus_ar_valid) begin
                    master_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd1;
                    master_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd1;
                    socbushandler_axilite2wishbone_next_state = 1'd1;
                end else begin
                    if (vexiiriscv_pbus_aw_valid) begin
                        master_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd0;
                        master_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd1;
                        socbushandler_axilite2wishbone_next_state = 2'd3;
                    end
                end
            end
        end
    endcase
end
