//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: Sync | Mode: Read-First 
// Port 1 | Read: Sync  | Write: ---- | 
reg [9:0] storage_29[0:15];
reg [9:0] storage_29_dat0;
reg [9:0] storage_29_dat1;
always @(posedge milan_clk) begin
	if (ctrlmailbox_ctrlmailbox_rx_cdc_wrport_we)
		storage_29[ctrlmailbox_ctrlmailbox_rx_cdc_wrport_adr] <= ctrlmailbox_ctrlmailbox_rx_cdc_wrport_dat_w;
	storage_29_dat0 <= storage_29[ctrlmailbox_ctrlmailbox_rx_cdc_wrport_adr];
end
always @(posedge sys_clk) begin
	storage_29_dat1 <= storage_29[ctrlmailbox_ctrlmailbox_rx_cdc_rdport_adr];
end
assign ctrlmailbox_ctrlmailbox_rx_cdc_wrport_dat_r = storage_29_dat0;
assign ctrlmailbox_ctrlmailbox_rx_cdc_rdport_dat_r = storage_29_dat1;


